// frontend/src/App.js
import React, { useState, useEffect } from 'react';
import Calendar from './Calendar';
import EventModal from './EventModal';
// import axios from 'axios'; // 暂时注释掉，不用后端
import './App.css';

// 不需要 API_URL 了

function App() {
  // 从 localStorage 读取保存的事件
  const [events, setEvents] = useState(() => {
    const savedEvents = localStorage.getItem('calendar-events');
    return savedEvents ? JSON.parse(savedEvents) : [];
  });
  
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [currentMonth, setCurrentMonth] = useState(new Date());

  // 当 events 变化时，保存到 localStorage
  useEffect(() => {
    localStorage.setItem('calendar-events', JSON.stringify(events));
  }, [events]);

  const handleDateClick = (date) => {
    setSelectedDate(date);
    setSelectedEvent(null);
    setIsModalOpen(true);
  };

  const handleEventClick = (event) => {
    setSelectedEvent(event);
    setSelectedDate(new Date(event.start_date));
    setIsModalOpen(true);
  };

  const handleSaveEvent = (eventData) => {
    if (selectedEvent) {
      // 编辑现有事件
      setEvents(events.map(e => 
        e.id === selectedEvent.id ? { ...eventData, id: selectedEvent.id } : e
      ));
    } else {
      // 创建新事件，生成临时ID
      const newEvent = {
        ...eventData,
        id: Date.now() // 用时间戳做临时ID
      };
      setEvents([...events, newEvent]);
    }
    setIsModalOpen(false);
  };

  const handleDeleteEvent = (eventId) => {
    setEvents(events.filter(e => e.id !== eventId));
    setIsModalOpen(false);
  };

  // 渲染部分完全不变
  return (
    <div className="App">
      <header className="app-header">
        <h1>📅 日历应用</h1>
      </header>
      <main>
        <Calendar
          events={events}
          onDateClick={handleDateClick}
          onEventClick={handleEventClick}
          currentMonth={currentMonth}
          setCurrentMonth={setCurrentMonth}
        />
        <EventModal
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSaveEvent}
          onDelete={handleDeleteEvent}
          selectedDate={selectedDate}
          event={selectedEvent}
        />
      </main>
    </div>
  );
}

export default App;
